inline study_movement::Result try_down(const study_grid::Grid& board,
                                       study_piece::Piece& current) noexcept {
    // Only a cleanly placed piece may be dropped.
    if (study_collision::classify(board, current) !=
        study_collision::Placement::clear) {
        return study_movement::Result::invalid;
    }

    // Work on a copy; commit only after all checks pass.
    study_piece::Piece candidate = current;

    // Widen the origin row to 64 bits before adding so the overflow check
    // cannot itself overflow.
    const std::int64_t widened =
        static_cast<std::int64_t>(candidate.origin.row) + 1;
    if (widened < static_cast<std::int64_t>(std::numeric_limits<int>::min()) ||
        widened > static_cast<std::int64_t>(std::numeric_limits<int>::max())) {
        return study_movement::Result::invalid;
    }
    candidate.origin.row = static_cast<int>(widened);

    // Classify the dropped candidate against the read-only board.
    const study_collision::Placement after =
        study_collision::classify(board, candidate);
    if (after == study_collision::Placement::outside ||
        after == study_collision::Placement::occupied) {
        return study_movement::Result::blocked; // obstacle reached
    }
    if (after != study_collision::Placement::clear) {
        return study_movement::Result::invalid; // unrepresentable mapping
    }

    current = candidate; // commit only after all checks pass
    return study_movement::Result::moved;
}

struct Counter {
    int elapsed = 0;    // ticks already spent in the current interval
    int interval = 30;  // ticks per gravity step; must stay positive
};

inline TickResult tick(const study_grid::Grid& board,
                       study_piece::Piece& piece,
                       Counter& counter) noexcept {
    // Validate the timer and the piece before touching anything.
    if (counter.interval <= 0 || counter.elapsed < 0 ||
        counter.elapsed >= counter.interval) {
        return TickResult::invalid;
    }
    if (study_collision::classify(board, piece) !=
        study_collision::Placement::clear) {
        return TickResult::invalid;
    }

    // The interval is not over yet: just record this tick.
    if (counter.elapsed < counter.interval - 1) {
        ++counter.elapsed;
        return TickResult::waiting;
    }

    // Final tick of the interval: try to fall.
    const study_movement::Result result = try_down(board, piece);
    if (result == study_movement::Result::invalid) {
        return TickResult::invalid; // counter and piece preserved
    }

    counter.elapsed = 0; // restart the interval on both moved and blocked
    return result == study_movement::Result::moved ? TickResult::moved
                                                   : TickResult::blocked;
}

Batch advance_ns(std::uint64_t elapsed_ns) noexcept {
    const bool clamped = elapsed_ns > max_frame_ns;
    const auto accepted = clamped ? max_frame_ns : elapsed_ns;
    // Clamp before multiplying: phase < 1e9, total < 7e9.
    const auto total = phase_ + accepted * rate;
    phase_ = total % units;
    return {static_cast<unsigned>(total / units), clamped};
}

std::optional<Batch> advance_seconds(double seconds) noexcept {
    if (!std::isfinite(seconds) || seconds < 0.0) return std::nullopt;
    const bool clamped = seconds > 0.1;
    // Bound before floating-to-integer conversion, even for enormous dt.
    const double accepted = clamped ? 0.1 : seconds;
    const auto ns = static_cast<std::uint64_t>(accepted * 1'000'000'000.0);
    auto batch = advance_ns(ns);
    batch.clamped = clamped;
    return batch;
}

class PendingHorizontal {
public:
    void capture(bool left_pressed, bool right_pressed) noexcept {
        left_ = left_ || left_pressed;
        right_ = right_ || right_pressed;
    }
    int consume() noexcept {
        const int direction = study_movement::horizontal_intent(left_, right_);
        left_ = right_ = false;
        return direction;
    }
private:
    bool left_ = false;
    bool right_ = false;
};

pending.capture(platform_key_pressed(Key::Left), platform_key_pressed(Key::Right));
const auto batch = clock.advance_seconds(frame.dt);
if (!batch) return 1;
bool changed = false;
for (unsigned i = 0; i < batch->ticks; ++i) {
    // Input is applied once, before gravity in the same tick.
    const auto move = study_collision::try_shift(board, piece, pending.consume());
    if (move == study_movement::Result::invalid) return 1;
    const auto fall = study_gravity::tick(board, piece, gravity);
    if (fall == study_gravity::TickResult::invalid) return 1;
    changed = changed || move == study_movement::Result::moved ||
                         fall == study_gravity::TickResult::moved;
}
// A batch may change CPU state several times. Upload only its final pose.
if (changed) {
    const auto updated_cells = study_piece::to_board(piece);
    if (!updated_cells) return 1;
    const auto updated_mesh = study_piece_view::make_visible_mesh(*updated_cells);
    if (!piece_buffer.replace_same_size(updated_mesh.vertices.data(),
                                        updated_mesh.count)) return 1;
    std::printf("piece=(%d,%d) gravity=%d/%d\n", piece.origin.row,
                piece.origin.column, gravity.elapsed, gravity.interval);
}
